    const remaining = deadline - Date.now();
    if (!Number.isSafeInteger(deadline) || remaining <= 0) {
        void work.catch(() => { });
        return false;
    }
    let timer;
    try {
        const clean = await Promise.race([work.catch(() => false), new Promise(resolve => {
                timer = setTimeout(() => resolve(false), remaining);
                timer.unref();
            })]);
