            request.resume();
            return;
        }
        const supplied = Buffer.from(request.headers.authorization ?? '');
        let authorized = supplied.length === authorization.length && timingSafeEqual(supplied, authorization);
        try {
            assertCurrent();
        }
        catch {
            authorized = false;
        }
        if (!authorized) {
            httpFailure(response, 401, 'forbidden');
            request.resume();
            return;
        }
        if (request.headers.host !== new URL(origin).host ||
            (request.headers.origin !== undefined && request.headers.origin !== origin)) {
            httpFailure(response, 403, 'forbidden');
            request.resume();
            return;
        }
        if (request.method !== 'POST') {
            httpFailure(response, 405, 'method-not-allowed');
            request.resume();
            return;
        }
        if (concurrent >= maxConcurrentRequests) {
            httpFailure(response, 503, 'busy');
            request.resume();
            return;
        }
        concurrent++;
        let mcp;
        let returnedCatalog;
        response.once('finish', () => {
            if (response.statusCode !== 200 || !returnedCatalog)
                return;
            try {
                assertCurrent();
                catalogReceipt = Object.freeze({
                    binding,
                    toolNames: Object.freeze([...returnedCatalog]),
                    sequence: ++catalogSequence,
                    servedAtMs: now(),
                });
            }
            catch {
                /* A revoked/expired response cannot publish current discovery evidence. */
            }
        });
        try {
            const body = await readBody(request, maxRequestBytes);
            assertCurrent();
            mcp = new Server({ name: 'legacy-agent-host-team', version: '0.1.0' }, {
                capabilities: { tools: {} },
                instructions: 'This endpoint captures your Team actor. Never send authority fields (from/actor/teamName/claudeDir/backend/run/member/generation). Mutating tools require a stable commandId chosen before first dispatch; preserve it on retry. Lookup uncertain outcomes; do not invent a replacement ID. Catalog is a partial P2 slice.',
            });
            mcp.onerror = () => {
                /* SDK error details never enter product logs or responses. */
            };
            mcp.setRequestHandler(ListToolsRequestSchema, () => {
                assertCurrent();
                const catalog = tools.list();
                returnedCatalog = catalog.map((tool) => tool.name).sort();
                return { tools: catalog };
            });
            mcp.setRequestHandler(CallToolRequestSchema, async (request) => {
                try {
                    assertCurrent();
                    const result = await tools.callAsync(request.params.name, request.params.arguments ?? {});
                    assertCurrent();
                    return result;
                }
                catch (error) {
                    return toolFailure(error);
                }
            });
            const transport = new StreamableHTTPServerTransport({ enableJsonResponse: true });
            active.add(mcp);
            // SDK 1.30's concrete optional callback accessors include undefined, while
            // its own Transport interface uses exact optionals. Runtime behavior is the
            // SDK's documented stateless transport; no host-service cast is involved.
            await mcp.connect(transport);
