        }
        catch (error) {
            const status = error instanceof McpToolFailure
                ? error.code === 'forbidden'
                    ? 401
                    : error.code === 'output-limit'
                        ? 413
                        : 400
                : 500;
            httpFailure(response, status, status === 413
                ? 'request-limit'
                : status === 401
                    ? 'forbidden'
                    : status === 400
                        ? 'invalid'
                        : 'internal');
        }
        finally {
            concurrent--;
            if (mcp) {
                active.delete(mcp);
                await mcp.close().catch(() => { });
            }
        }
    }
    await new Promise((resolve, reject) => {
        server.once('error', reject);
        server.listen(port, '127.0.0.1', () => {
            server.off('error', reject);
            resolve();
        });
    });
    const address = server.address();
    if (!address || typeof address === 'string') {
        server.close();
        throw new McpToolFailure('invalid');
    }
    origin = `http://127.0.0.1:${address.port}`;
    let closing;
    return Object.freeze({
        url: origin + path,
        bearerToken,
        binding,
        getCatalogReceipt: () => {
            try {
                assertCurrent();
                return catalogReceipt ? structuredClone(catalogReceipt) : undefined;
            }
            catch {
                return undefined;
            }
        },
        revoke: () => {
            revoked = true;
        },
        close: () => {
            revoked = true;
            closing ??= (async () => {
                await Promise.allSettled([...active].map((entry) => entry.close()));
                await new Promise((resolve, reject) => {
                    server.close((error) => (error ? reject(error) : resolve()));
                    server.closeAllConnections();
                });
            })();
            return closing;
        },
    });
}
